import { pathToFileURL } from "node:url";
import repositories from "../src/repositories.json" with { type: "json" };

// Print, rather than edit a checkout. Callers review the generated file in a PR.
export function listener(repo, revision) {
  const policy = repositories[repo];
  if (!policy) throw new Error("Repository is not enrolled");
  if (!/^[a-f0-9]{40}$/.test(revision))
    throw new Error("Pin the action to a full reviewed Git commit");
  const workflows = Object.values(policy.workflows)
    .map((workflow) => `      - ${JSON.stringify(workflow.name)}`)
    .join("\n");
  return `# Generated by joswayski/automation scripts/listener.mjs. No failing-run checkout.
name: Amp CI repair

on:
  workflow_run:
    workflows:
${workflows}
    types: [completed]
    branches: [main]

permissions:
  actions: read
  contents: read
  issues: write
  pull-requests: read

# Serialize durable reservations; retain up to 100 pending completion events.
concurrency:
  group: amp-ci-repair
  queue: max

jobs:
  repair:
    if: >-
      vars.AMP_REPAIR_ENABLED == 'true' &&
      github.repository == '${repo}' &&
      github.event.workflow_run.head_repository.full_name == github.repository &&
      github.event.workflow_run.head_branch == 'main' &&
      contains(fromJSON('["failure","cancelled","timed_out"]'), github.event.workflow_run.conclusion)
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    steps:
      - name: Investigate failure with Amp
        uses: joswayski/automation@${revision}
        with:
          enabled: \${{ vars.AMP_REPAIR_ENABLED }}
          dry-run: \${{ vars.AMP_REPAIR_DRY_RUN == 'true' }}
          daily-limit: \${{ vars.AMP_REPAIR_DAILY_LIMIT || '3' }}
          github-token: \${{ github.token }}
          amp-api-key: \${{ secrets.AMP_API_KEY }}
`;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.stdout.write(listener(process.argv[2], process.argv[3]));
}
